from save_review import save
save(1318,{5:'爆燃武器的杀伤力超过大多数同等尺寸的兵器，但其原理鲜为人知，即使技术最强的机械修会铸造世界也很难仿造。它能使有机物发生爆燃，将血肉猛烈焚为灰烬，并喷出烈火。直接命中的目标往往会整个人燃烧起来，连累附近同伴一同遭殃。',7:'星际战士军团初创时，爆燃武器曾相当常见；到了荷鲁斯之乱时期，它们已日益稀少，被用途更灵活、制造更容易的爆矢枪取代。乱期间铸造世界的损失，又加速了它们在帝国中的衰落。',9:'特勒拉克型甚至比普罗透斯型更古老、更不祥，其名称暗示着与纷争时代恐怖技术的阴暗联系。由于爆燃武器缺乏可靠供应，许多特勒拉克型被重新启用，并在星际战士军械库中得到精心维护。',13:'阿泰勒斯·努梅昂的长刀——集成了爆燃武器。',15:'Artellus Numeon 阿泰勒斯·努梅昂',17:'爆燃蛇铳——由机械教、机械修会和阿斯塔特军团使用。',29:'爆燃爆破枪——技术祭司主宰者使用。',33:'空腔爆燃铳——肯特卡终结者使用。',36:'爆燃焚化器——安装于铁熊部队胸部。',38:'爆燃隼炮——用于德雷都型无畏机甲。',40:'爆燃哨兵——由机仆大脑控制的双联爆燃突击铳，安装于特里亚罗斯装甲运输车等大型机械教战争机器。',46:'爆燃长炮——由辅军精锐毁灭士、阿卡斯托斯型帝国骑士、战术支援小队和蔑视者型无畏机甲使用。',57:'爆燃射线炮——安装于天命型侍从帝国骑士。',63:'爆燃破坏炮——安装于战将级帝国泰坦。'},notes={9:'原译将Volkite误作热熔，已恢复爆燃；关于特勒拉克与普罗透斯孰早，1323同篇内部也存在相反描述，保留源文差异。'},terms=[('Volkite Weapon','爆燃武器'),('Telerac Pattern','特勒拉克型'),('Volkite Serpenta','爆燃蛇铳'),('Neo-Volkite Pistol','新型爆燃手枪'),('Volkite Charger','爆燃突击铳'),('Volkite Caliver','爆燃火铳'),('Volkite Blaster','爆燃爆破枪'),('Volkite Cavitor','空腔爆燃铳'),('Volkite Incinerator','爆燃焚化器'),('Volkite Falconet','爆燃隼炮'),('Volkite Sentinel','爆燃哨兵'),('Volkite Saker','爆燃长管炮'),('Volkite Demi-Culverin','爆燃半长炮'),('Volkite Culverin','爆燃长炮'),('Volkite Carronade','爆燃短重炮'),('Volkite Cardanelle','爆燃臼炮'),('Volkite Combustor','爆燃燃烧炮'),('Volkite Veuglaire','爆燃射线炮'),('Volkite Chieorovile','爆燃邪光'),('Volkite Eradicator','爆燃根除者'),('Volkite Destructor','爆燃破坏炮'),('Volkite Storm Accelerator','爆燃风暴加速炮'),('Triaros Armoured Conveyer','特里亚罗斯装甲运输车')])
save(1319,{2:'爆燃蛇铳是最小型的爆燃武器，外形类似手枪，可单手持用。'},terms=[('Volkite Serpenta','爆燃蛇铳')])
save(1320,{2:'爆燃突击铳是阿斯塔特军团和机械教在大远征及荷鲁斯之乱期间使用的爆燃武器。',6:'它的射程和威力虽不及较大型号，却保留了爆燃光束的杀伤特性，也让持用者行动更加灵活。军团战术支援小队经常装备这种武器。'},notes={2:'Legiones Astartes为阿斯塔特军团，并非阿斯塔特老兵。'},terms=[('Volkite Charger','爆燃突击铳')])
save(1321,{2:'爆燃火铳是阿斯塔特军团和机械教在大远征及荷鲁斯之乱期间使用的爆燃武器。',6:'它是步枪形制的爆燃武器，对血肉和骨骼杀伤极强。执行机动作战的军团战术支援小队经常使用它，其火力胜过更常见的爆矢枪。',9:'火星—欧米伽型——因杀伤效果可怖、破坏力强，深受午夜领主战术支援小队青睐。'},terms=[('Volkite Caliver','爆燃火铳'),('Mars-Omega Pattern','火星—欧米伽型')])
save(1322,{2:'空腔爆燃铳是午夜领主肯特卡终结者使用的重型爆燃武器，附有链锯刃。',4:'Volkite Cavitor 空腔爆燃铳',6:'它是诺斯特拉莫生产的一种爆燃武器改型，在这个饱受蹂躏的世界上，是少见的失落技术遗存。拆除安全装置后，它能在较短距离内射出更为分散的光束。'},terms=[('Volkite Cavitor','空腔爆燃铳')])
save(1323,{2:'爆燃长炮是帝国军械库中威力最强的单兵携行爆燃武器。其光束对有机物杀伤极大，能使血肉猛烈爆燃，化作灰烬与喷涌的火焰。',8:'蔑视者型无畏机甲凭借强大的反应堆和承载能力，可以安装这种双联爆燃长炮。',9:'Telerac Pattern 特勒拉克型',11:'特勒拉克型甚至比普罗透斯型更古老、更不祥，其名称暗示着与纷争时代深处那些恐怖技术的阴暗联系。由于爆燃武器缺乏可靠供应，许多特勒拉克型奉帝皇之名重新服役，并在阿斯塔特修会军械库中得到精心维护。',13:'Telerac Pattern Volkite Culverin 特勒拉克型爆燃长炮',16:'爆燃长炮的普罗透斯型早于特勒拉克型。'},notes={16:'本句英文称普罗透斯型更早，与上文特勒拉克型更古老的说法直接矛盾；两处按各自原文保留，待核原始出版资料。'},terms=[('Volkite Culverin','爆燃长炮'),('Telerac Pattern','特勒拉克型')])
save(1324,{2:'爆燃臼炮是安装于星际战士奎托斯重型坦克的重型爆燃武器，专门用于焚熔成群的敌方步兵。',4:'Volkite Cardanelle 爆燃臼炮'},notes={4:'图注原译短重炮与Carronade混淆，按本条Cardanelle统一为臼炮；不据译名增添曲射性能。'},terms=[('Volkite Cardanelle','爆燃臼炮')])
save(1325,{2:'爆燃隼炮是安装于德雷都型无畏机甲的爆燃武器。',4:'Deredeo Dreadnought with arm-mounted Volkite Falconets 臂部装备爆燃隼炮的德雷都型无畏机甲'},terms=[('Volkite Falconet','爆燃隼炮')])
save(1326,{2:'爆燃短重炮是阿斯塔特军团和机械教在大远征及荷鲁斯之乱期间使用的爆燃武器。',6:'它是爆燃武器家族中的大型版本，安装于残暴刃坦克，一次横扫便能摧毁敌方大型目标。'},terms=[('Volkite Carronade','爆燃短重炮'),('Fellglaive','残暴刃坦克')])
save(1327,{2:'爆燃长管炮是大远征和荷鲁斯之乱期间，有时安装于星际战士军刀突击坦克的重型爆燃武器。',4:'Sabre Tank Hunter with a Volkite Saker 装备爆燃长管炮的军刀反坦克车',6:'它由爆燃长炮改进而来，经过优化，可在军刀高速机动时，以高能粒子束覆盖尽可能宽的区域。虽然无法穿透重型装甲，却足以扫灭重装步兵，撕碎轻型载具的车体。'},terms=[('Volkite Saker','爆燃长管炮')])
